def recite(start_verse, end_verse):
    animals = [
        {"name": "fly", "line": ""},
        {"name": "spider", "line": "It wriggled and jiggled and tickled inside her."},
        {"name": "bird", "line": "How absurd to swallow a bird!"},
        {"name": "cat", "line": "Imagine that, to swallow a cat!"},
        {"name": "dog", "line": "What a hog, to swallow a dog!"},
        {"name": "goat", "line": "Just opened her throat and swallowed a goat!"},
        {"name": "cow", "line": "I don't know how she swallowed a cow!"},
        {"name": "horse", "line": "She's dead, of course!"},
    ]

    def get_verse(i):
        if i == 8:
            return [
                "I know an old lady who swallowed a horse.",
                "She's dead, of course!",
            ]

        lines = [f"I know an old lady who swallowed a {animals[i-1]['name']}."]
        if animals[i-1]['line']:
            lines.append(animals[i-1]['line'])

        if i > 1:
            for j in range(i - 1, 0, -1):
                prey = animals[j-1]['name']
                predator = animals[j]['name']
                if j == 2:
                    lines.append(f"She swallowed the {predator} to catch the {prey} that wriggled and jiggled and tickled inside her.")
                else:
                    lines.append(f"She swallowed the {predator} to catch the {prey}.")

            lines.append("I don't know why she swallowed the fly. Perhaps she'll die.")
        else:
            lines.append("I don't know why she swallowed the fly. Perhaps she'll die.")

        return lines

    result = []
    for i in range(start_verse, end_verse + 1):
        result.extend(get_verse(i))
        if i < end_verse:
            result.append("")

    return result
