```python
def grep(pattern, flags, files):
    flag_list = flags.split()

    # Flags
    n_flag = "-n" in flag_list
    l_flag = "-l" in flag_list
    i_flag = "-i" in flag_list
    v_flag = "-v" in flag_list
    x_flag = "-x" in flag_list

    multiple_files = len(files) > 1

    result = []

    for file_name in files:
        with open(file_name, 'r') as f:
            file_lines = f.readlines()

        file_matches = []

        for i, line in enumerate(file_lines):
            line_content = line.rstrip('\n')

            # Compare logic
            match = False
            if i_flag:
                if x_flag:
                    match = (pattern.lower() == line_content.lower())
                else:
                    match = (pattern.lower() in line_content.lower())
            else:
                if x_flag:
                    match = (pattern == line_content)
                else:
                    match = (pattern in line_content)

            if v_flag:
                match = not match

            if match:
                if l_flag:
                    file_matches = [file_name]
                    break # Only need one match for -l

                # Format the line
                line_to_add = line_content

                if n_flag:
                    line_to_add = f"{i+1}:{line_to_add}"

                if multiple_files:
                    line_to_add = f"{file_name}:{line_to_add}"

                file_matches.append(line_to_add)

        result.extend(file_matches)

    return "\n".join(result) + ("\n" if result else "")
```

