class Scale:
    def __init__(self, tonic):
        self.tonic = tonic
        self.sharps = ["A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#"]
        self.flats = ["A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab"]

        sharp_keys = ["G", "D", "A", "E", "B", "F#", "e", "b", "f#", "c#", "g#", "d#"]

        if self.tonic in ["C", "a"]:
            use_sharps = True
        elif self.tonic in sharp_keys:
            use_sharps = True
        else:
            use_sharps = False

        self.notes = self.sharps if use_sharps else self.flats

        t = self.tonic[0].upper()
        if len(self.tonic) > 1:
            t += self.tonic[1].lower()

        idx = self.notes.index(t)
        self.notes = self.notes[idx:] + self.notes[:idx]

    def chromatic(self):
        return self.notes

    def interval(self, intervals):
        result = [self.notes[0]]
        idx = 0
        interval_map = {'m': 1, 'M': 2, 'A': 3}
        for i in intervals:
            idx += interval_map[i]
            result.append(self.notes[idx % 12])
        return result
